/**
 * "Test connection" button of the plugin settings page: asks knowledge_ajax.php (action checkhealth,
 * Moodle session + sesskey) for the backend's status and draws it with green / yellow / red badges.
 * Everything is written with textContent.
 *
 * @module     local_libiac/connection_test
 */
define("local_libiac/connection_test", [], function() {
    var COLORS = {ok: 'success', degraded: 'warning', error: 'danger'};

    var init = function(config) {
        var button = document.querySelector('[data-action="test-connection"]');
        var out = document.querySelector('[data-region="diagnostics"]');
        if (!button || !out) {
            return;
        }
        var strings = config.strings;

        var row = function(label, state, detail) {
            var line = document.createElement('div');
            line.className = 'mb-2';
            var badge = document.createElement('span');
            var color = COLORS[state] || 'danger';
            badge.className = 'badge badge-' + color + ' bg-' + color + ' mr-2 me-2';
            badge.textContent = strings['diag_state_' + (COLORS[state] ? state : 'error')];
            var name = document.createElement('strong');
            name.textContent = label;
            line.appendChild(badge);
            line.appendChild(name);
            if (detail) {
                var text = document.createElement('div');
                text.className = 'small text-muted';
                text.textContent = detail;
                line.appendChild(text);
            }
            out.appendChild(line);
        };

        var render = function(health) {
            out.textContent = '';
            if (health.state === 'unreachable') {
                row(strings.diag_server, 'error', strings.diag_unreachable);
                return;
            }
            if (health.state === 'badsignature' || health.state === 'forbidden') {
                row(strings.diag_server, 'error', strings['diag_' + health.state]);
                return;
            }
            if (!health.components) {
                row(strings.diag_server, 'error', strings.diag_servererror);
                return;
            }
            var latency = strings.diag_latency.split('{$a->roundtrip}').join(String(health.roundtrip_ms))
                .split('{$a->latency}').join(String(health.latency_ms));
            row(strings.diag_server, 'ok', latency + ' ' + strings.diag_signature_ok);
            row(strings.diag_database, health.components.database.status, health.components.database.message);
            row(strings.diag_llm, health.components.llm_provider.status, health.components.llm_provider.message);
        };

        button.addEventListener('click', function() {
            button.disabled = true;
            out.textContent = strings.diag_testing;
            var url = config.ajaxurl + '?action=checkhealth&courseid=' + config.courseid +
                '&sesskey=' + encodeURIComponent(config.sesskey);
            fetch(url, {credentials: 'same-origin'}).then(function(response) {
                return response.json().then(function(data) {
                    if (!response.ok || !data.health) {
                        throw new Error('bad');
                    }
                    render(data.health);
                });
            }).catch(function() {
                out.textContent = '';
                row(strings.diag_server, 'error', strings.diag_notconfigured);
            }).then(function() {
                button.disabled = false;
            });
        });
    };

    return {init: init};
});
